function renderBlocks(lines: Line[]): string {
  const out: string[] = []
  let i = 0
  while (i < lines.length) {
    const { text } = lines[i]

    if (isBlank(text)) {
      i++
      continue
    }

    const fence = FENCE.exec(text)
    if (fence) {
      const marker = fence[1]
      const lang = fence[2]
      const body: string[] = []
      i++
