    const found = searchNotes(sorted, query)
    return tagFilter ? found.filter((n) => hasTag(n.content, tagFilter)) : found
  }, [sorted, query, tagFilter])
  const tagCounts = useMemo(() => countTags(notes.map((n) => n.content)), [notes])
