    [notes, activeId],
  )
  const active = notes.find((n) => n.id === activeId) ?? null
  const previewHtml = useMemo(() => (active ? renderMarkdown(active.content) : ''), [active])
  const words = useMemo(() => (active ? wordCount(active.content) : 0), [active])

